args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?director ?dirLabel WHERE {
  { <http://dbpedia.org/resource/My_Neighbor%27s_Wife_(1925_film)> dbo:director ?director }
  UNION
  { <http://dbpedia.org/resource/My_Neighbor%27s_Wife_(1925_film)> dbp:director ?director }
  OPTIONAL { ?director rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = 'en') }
}

PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT ?p ?o WHERE {
  <http://dbpedia.org/resource/My_Neighbor%27s_Wife_(1925_film)> ?p ?o .
} LIMIT 200

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?film ?label ?date WHERE {
  ?film rdfs:label ?label .
  FILTER(lang(?label) = 'en')
  FILTER regex(?label, "My Neighbor's Wife", "i")
  OPTIONAL { ?film dbo:releaseDate ?date . }
  OPTIONAL { ?film dbp:releaseDate ?date . }
  OPTIONAL { ?film dbp:released ?date . }
  OPTIONAL { ?film dbp:year ?date . }
} LIMIT 50

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?p ?o WHERE {
  ?film rdfs:label "My Neighbor's Wife (1925 film)"@en .
  ?film ?p ?o .
} LIMIT 200

